import re
def strip(src):
    out = []
    for line in src.splitlines():
        q, i, cut = None, 0, len(line)
        while i < len(line):
            c = line[i]
            if q:
                if c == '\\':
                    i += 2
                    continue
                if c == q:
                    q = None
            elif c in '"\'':
                q = c
            elif line.startswith('--', i):
                cut = i
                break
            i += 1
        out.append(line[:cut])
    return '\n'.join(out)
